// gradeUtils.ts

// Enum for enrollment status
export enum EnrollmentStatus {
    Passing = "PASSING",
    Probation = "PROBATION"
}

// Named export with explicit return type annotation
export const computeAverage = (prelim: number, midterm: number, final: number): number => {
    return (prelim + midterm + final) / 3;
};

// Default export returning an EnrollmentStatus enum
const getStatus = (average: number): EnrollmentStatus => {
    return average >= 75 ? EnrollmentStatus.Passing : EnrollmentStatus.Probation;
};

export default getStatus;